/**
 * @name Terminal output with user input
 * @description Checking if user input can flow to terminal output functions
 * @kind path-problem
 * @problem.severity warning
 * @id py/terminal-injection
 * @tags security
 *        external/cwe/cwe-150
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module TerminalOutputConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for print/write operations
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("print").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("sys").getMember("stdout").getMember("write").getACall() and
      sink = call.getArg(0)
    )
  }
}

module TerminalOutputFlow = TaintTracking::Global<TerminalOutputConfig>;
import TerminalOutputFlow::PathGraph

from TerminalOutputFlow::PathNode source, TerminalOutputFlow::PathNode sink
where TerminalOutputFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User input reaches terminal output at $@.", source.getNode(), "user input"

/**
 * @name File system access with user input
 * @description Checking if user input can flow to file system operations
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module FileAccessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module FileAccessFlow = TaintTracking::Global<FileAccessConfig>;
import FileAccessFlow::PathGraph

from FileAccessFlow::PathNode source, FileAccessFlow::PathNode sink
where FileAccessFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User input reaches file system operation at $@.", source.getNode(), "user input"

/**
 * @name Terminal injection vulnerability
 * @description Checking if user input can flow to terminal output/escape sequences
 * @kind path-problem
 * @problem.severity error
 * @id py/terminal-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module TerminalInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for writes to sys.stdout, sys.stderr, or print statements
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("print").getACall() and
      sink = call
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("sys").getMember("stdout").getMember("write").getACall() and
      sink = call
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("sys").getMember("stderr").getMember("write").getACall() and
      sink = call
    )
  }
}

module TerminalInjectionFlow = TaintTracking::Global<TerminalInjectionConfig>;
import TerminalInjectionFlow::PathGraph

from TerminalInjectionFlow::PathNode source, TerminalInjectionFlow::PathNode sink
where TerminalInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Terminal injection from $@.", source.getNode(), "user input"
